export class BookmarkService {
  constructor({ store, metadataClient, clock = () => new Date() }) {
    this.store = store;
    this.metadataClient = metadataClient;
    this.clock = clock;
  }

  list() {
    return this.store.list().sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  }

  #require(id) {
    const bookmark = this.store.get(id);
    if (!bookmark) throw new AppError('NOT_FOUND', 'Bookmark not found.', 404);
    return bookmark;
  }

  async save({ url, label }) {
    const canonicalUrl = canonicalizeUrl(url);
    const existing = this.store.findByCanonicalUrl(canonicalUrl);
    if (existing) return { kind: 'duplicate', location: existing.archived ? 'archive' : 'library', bookmark: existing };

    const metadata = await this.metadataClient.retrieve(canonicalUrl);
    const now = this.clock().toISOString();
    const firstLabel = normalizedLabel(label);
    const bookmark = await this.store.insert({
      canonicalUrl,
      url: canonicalUrl,
      ...metadata,
      labels: firstLabel ? [firstLabel] : [],
      read: false,
      archived: false,
      createdAt: now,
      updatedAt: now
    });
    return { kind: 'created', bookmark };
  }

  async refresh(id) {
    const bookmark = this.#require(id);
    const metadata = await this.metadataClient.retrieve(bookmark.url);
    return this.store.update(id, { ...metadata, updatedAt: this.clock().toISOString() });
  }

  async addLabel(id, rawLabel) {
    const bookmark = this.#require(id);
    const label = normalizedLabel(rawLabel);
    if (!label) throw new AppError('EMPTY_LABEL', 'Enter a label.', 400);
    const duplicate = bookmark.labels.some((item) => item.toLocaleLowerCase() === label.toLocaleLowerCase());
    if (duplicate) return { added: false, bookmark };
    const updated = await this.store.update(id, { labels: [...bookmark.labels, label], updatedAt: this.clock().toISOString() });
    return { added: true, bookmark: updated };
  }

  async setRead(id, read) {
    this.#require(id);
    return this.store.update(id, { read: Boolean(read), updatedAt: this.clock().toISOString() });
  }

  async archive(id) {
    this.#require(id);
    return this.store.update(id, { archived: true, updatedAt: this.clock().toISOString() });
  }

  async restore(id) {
    this.#require(id);
    return this.store.update(id, { archived: false, updatedAt: this.clock().toISOString() });
  }

  async restoreAndRefresh(id) {
    const bookmark = this.#require(id);
    const metadata = await this.metadataClient.retrieve(bookmark.url);
    return this.store.update(id, { ...metadata, archived: false, updatedAt: this.clock().toISOString() });
  }
}
import { AppError } from './errors.js';
import { sourceFromUrl } from './urls.js';

const ENTITY_MAP = new Map([
  ['amp', '&'], ['quot', '"'], ['apos', "'"], ['lt', '<'], ['gt', '>'], ['nbsp', ' ']
]);

function decodeEntities(value) {
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, entity) => {
    if (entity[0] === '#') {
      const radix = entity[1]?.toLowerCase() === 'x' ? 16 : 10;
      const digits = radix === 16 ? entity.slice(2) : entity.slice(1);
      const codePoint = Number.parseInt(digits, radix);
      return Number.isFinite(codePoint) ? String.fromCodePoint(codePoint) : match;
    }
    return ENTITY_MAP.get(entity.toLowerCase()) ?? match;
  });
}

function cleanText(value) {
  return decodeEntities(value.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim());
}

function attributesFromTag(tag) {
  const attributes = {};
  for (const match of tag.matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g)) {
    attributes[match[1].toLowerCase()] = match[2] ?? match[3] ?? match[4] ?? '';
  }
  return attributes;
}

export function extractPageMetadata(html, finalUrl) {
  const meta = [...html.matchAll(/<meta\b[^>]*>/gi)].map((match) => attributesFromTag(match[0]));
  const findMeta = (...names) => meta.find((attrs) => names.includes((attrs.property ?? attrs.name ?? '').toLowerCase()))?.content;
  const titleMatch = html.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i);
  const title = cleanText(findMeta('og:title', 'twitter:title') ?? titleMatch?.[1] ?? '');
  const description = cleanText(findMeta('description', 'og:description', 'twitter:description') ?? '');

  if (!title || !description) {
    throw new AppError('METADATA_UNAVAILABLE', 'We could not get this page’s title and description.', 422);
  }

  return { title, description, source: sourceFromUrl(finalUrl) };
}

export class MetadataClient {
  constructor({ timeoutMs = 8000, fetchImpl = fetch } = {}) {
    this.timeoutMs = timeoutMs;
    this.fetchImpl = fetchImpl;
  }

  async retrieve(url) {
    try {
      const response = await this.fetchImpl(url, {
        redirect: 'follow',
        signal: AbortSignal.timeout(this.timeoutMs),
        headers: { 'user-agent': 'PersonalBookmarkLibrary/1.0 (+bookmark metadata reader)' }
      });
      if (!response.ok) throw new Error(`Page returned ${response.status}`);
      const contentType = response.headers.get('content-type') ?? '';
      if (!contentType.toLowerCase().includes('text/html')) throw new Error('Page is not HTML');
      const html = await response.text();
      return extractPageMetadata(html, response.url || url);
    } catch (error) {
      if (error instanceof AppError) throw error;
      throw new AppError('METADATA_UNAVAILABLE', 'We could not get this page’s title and description.', 422);
    }
  }
}
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

const EMPTY_STATE = { nextId: 1, bookmarks: [] };

export class BookmarkStore {
  static async open(filePath) {
    const store = new BookmarkStore(filePath);
    await store.#load();
    return store;
  }

  constructor(filePath) {
    this.filePath = filePath;
    this.state = structuredClone(EMPTY_STATE);
    this.writeChain = Promise.resolve();
  }

  async #load() {
    try {
      const parsed = JSON.parse(await readFile(this.filePath, 'utf8'));
      if (!Array.isArray(parsed.bookmarks) || !Number.isInteger(parsed.nextId)) throw new Error('Invalid bookmark data');
      this.state = parsed;
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
      await this.#persist();
    }
  }

  async #persist() {
    const snapshot = JSON.stringify(this.state, null, 2);
    this.writeChain = this.writeChain.then(async () => {
      await mkdir(dirname(this.filePath), { recursive: true });
      const temporaryPath = `${this.filePath}.tmp`;
      await writeFile(temporaryPath, snapshot, 'utf8');
      await rename(temporaryPath, this.filePath);
    });
    return this.writeChain;
  }

  list() {
    return structuredClone(this.state.bookmarks);
  }

  findByCanonicalUrl(canonicalUrl) {
    const bookmark = this.state.bookmarks.find((item) => item.canonicalUrl === canonicalUrl);
    return bookmark ? structuredClone(bookmark) : null;
  }

  get(id) {
    const bookmark = this.state.bookmarks.find((item) => item.id === Number(id));
    return bookmark ? structuredClone(bookmark) : null;
  }

  async insert(bookmark) {
    const stored = { ...structuredClone(bookmark), id: this.state.nextId++ };
    this.state.bookmarks.push(stored);
    await this.#persist();
    return structuredClone(stored);
  }

  async update(id, changes) {
    const index = this.state.bookmarks.findIndex((item) => item.id === Number(id));
    if (index === -1) return null;
    this.state.bookmarks[index] = { ...this.state.bookmarks[index], ...structuredClone(changes) };
    await this.#persist();
    return structuredClone(this.state.bookmarks[index]);
  }
}
import { AppError } from './errors.js';

export function canonicalizeUrl(value) {
  let parsed;
  try {
    parsed = new URL(String(value ?? '').trim());
  } catch {
    throw new AppError('INVALID_URL', 'Enter a full web address, such as https://example.com', 400);
  }

  if (!['http:', 'https:'].includes(parsed.protocol) || !parsed.hostname) {
    throw new AppError('INVALID_URL', 'Enter a full web address, such as https://example.com', 400);
  }

  parsed.hash = '';
  parsed.hostname = parsed.hostname.toLowerCase();
  if ((parsed.protocol === 'https:' && parsed.port === '443') || (parsed.protocol === 'http:' && parsed.port === '80')) {
    parsed.port = '';
  }
  if (parsed.pathname === '/') parsed.pathname = '';
  return parsed.toString();
}

export function sourceFromUrl(value) {
  return new URL(value).hostname.replace(/^www\./i, '');
}
