  --fern: #dce9df;
  --cream: #f6f2e9;
  --surface: #fffdf8;
  --ink: #1d2925;
  --muted: #68736e;
  --border: #d8d9d1;
  --danger: #9b3b32;
  --warning: #725816;
  --shadow: 0 15px 45px rgba(28, 49, 41, .07);
}

* { box-sizing: border-box; }
