.sidebar-heading { margin: 0 9px 8px; color: var(--muted); font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.sidebar-rule { height: 1px; margin: 14px 5px; background: var(--border); }
.nav-item { display: flex; width: 100%; justify-content: space-between; align-items: center; gap: 8px; margin: 2px 0; padding: 9px 10px; color: var(--ink); background: transparent; text-align: left; font-size: 13px; }
.nav-item:hover { background: #eceee7; }
.nav-item.active { color: white; background: var(--forest-2); }
.count-pill { min-width: 24px; padding: 2px 7px; border-radius: 999px; color: var(--muted); background: #e6e8e1; text-align: center; font-size: 11px; }
.nav-item.active .count-pill { color: var(--forest); background: white; }
.content { min-width: 0; }
.content-head { display: flex; justify-content: space-between; align-items: end; margin-bottom: 13px; }
.content-head h2 { margin: 0; font: 700 25px/1.15 Georgia, serif; }
.content-head > span { color: var(--muted); font-size: 13px; }
.search-wrap { position: relative; }
.search-wrap > span { position: absolute; top: 50%; left: 15px; transform: translateY(-50%); color: var(--muted); font-size: 20px; }
.search-wrap input { padding-left: 45px; border-radius: 13px; }
.filter-summary { min-height: 20px; margin: 8px 2px 10px; color: var(--muted); font-size: 12px; }

.notice { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-bottom: 12px; padding: 14px 16px; border-radius: 13px; font-size: 13px; line-height: 1.4; }
.notice.success { color: #294c3a; border: 1px solid #bed1c2; background: #e7f0e8; }
.notice.duplicate { color: #51451e; border: 1px solid #dcd0a9; background: #f8f0d5; }
.notice strong { display: block; margin-bottom: 2px; }
.notice-actions { display: flex; flex: 0 0 auto; gap: 8px; }
.notice button { min-height: 36px; padding: 8px 11px; }
.notice .secondary { color: var(--ink); background: rgba(255,255,255,.7); }
.notice .secondary:hover { background: white; }

.bookmark-list { display: grid; gap: 12px; }
.bookmark-item { overflow: hidden; border: 1px solid var(--border); border-radius: 17px; background: var(--surface); box-shadow: 0 8px 26px rgba(28,49,41,.045); }
.bookmark-card { position: relative; display: grid; grid-template-columns: 44px 1fr auto; gap: 15px; padding: 20px; transition: border-color .15s ease, transform .15s ease, background .15s ease; }
.bookmark-card:hover { background: #fffefa; }
.card-link { position: absolute; inset: 0; z-index: 1; border-radius: 17px; }
.card-link:focus { outline: 3px solid rgba(36,93,77,.24); outline-offset: -3px; }
.site-mark { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 11px; color: white; background: var(--forest); font: 700 18px Georgia, serif; }
.bookmark-copy { min-width: 0; }
.source { margin: 0 0 4px; color: var(--forest-2); font-size: 11px; font-weight: 800; letter-spacing: .04em; }
.bookmark-copy h3 { display: -webkit-box; overflow: hidden; margin: 0 0 6px; font: 700 20px/1.25 Georgia, serif; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.description { display: -webkit-box; overflow: hidden; margin: 0; color: #5d6863; line-height: 1.48; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
.tag-list { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 11px; pointer-events: none; }
.tag { padding: 4px 8px; border-radius: 999px; color: #365747; background: #e7eee5; font-size: 11px; font-weight: 750; }
.saved-time { margin: 10px 0 0; color: #8a918d; font-size: 11px; }
.card-actions { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: flex-end; gap: 8px; min-width: 115px; }
.status { padding: 5px 8px; border-radius: 999px; color: var(--warning); background: #f4eac7; font-size: 11px; font-weight: 800; }
.status.read { color: #386047; background: var(--fern); }
.card-actions button { min-height: 33px; padding: 7px 10px; color: var(--forest-2); border: 1px solid #bfd0c5; background: white; font-size: 12px; }
.card-actions button:hover { color: white; background: var(--forest-2); }
.card-actions .archive-action { color: var(--muted); border-color: var(--border); }
.card-actions .archive-action:hover { color: var(--ink); background: #eeeee8; }

.label-editor { display: flex; gap: 9px; align-items: end; padding: 13px 20px 16px 79px; border-top: 1px solid var(--border); background: #faf8f1; }
.label-editor > div { flex: 1; }
.label-editor label { margin-bottom: 5px; }
.label-editor input { padding: 9px 11px; }
.label-editor button { min-height: 39px; padding: 8px 13px; }
.label-feedback { margin: 0; padding: 0 20px 13px 79px; color: var(--warning); background: #faf8f1; font-size: 12px; font-weight: 700; }

.empty-state { padding: 48px 24px; border: 1px dashed #c9cbc3; border-radius: 17px; text-align: center; background: rgba(255,255,255,.3); }
.empty-mark { display: block; margin-bottom: 8px; color: var(--forest-2); font-size: 34px; }
.empty-state h3 { margin: 0 0 7px; font: 700 20px/1.2 Georgia, serif; }
.empty-state p { margin: 0 auto; max-width: 500px; color: var(--muted); line-height: 1.5; }
.empty-state button { margin-top: 15px; padding: 10px 14px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

@media (max-width: 820px) {
  .app-shell { width: min(100% - 28px, 1180px); }
  .capture { grid-template-columns: 1fr; gap: 22px; padding: 24px; }
  .workspace { grid-template-columns: 1fr; }
  .sidebar { position: static; }
}

@media (max-width: 590px) {
  .topbar { align-items: flex-start; gap: 16px; }
  .summary { display: none; }
  .save-row { flex-direction: column; }
  .save-row button { min-height: 44px; }
  .bookmark-card { grid-template-columns: 40px 1fr; }
  .card-actions { grid-column: 2; flex-direction: row; flex-wrap: wrap; align-items: center; }
  .label-editor { padding-left: 20px; }
  .label-feedback { padding-left: 20px; }
}
